let corpo = {};
try { corpo = insomnia.response.json(); } catch (e) { corpo = {}; }

insomnia.test("Status HTTP 200", () => {
  insomnia.expect(insomnia.response.code).to.eql(200);
});

insomnia.test("`data` é uma lista", () => {
  insomnia.expect(corpo.data).to.be.an('array');
});

insomnia.test("Cada item traz setor, quantidade e maior atraso, com valores válidos", () => {
  corpo.data.forEach((i) => {
    insomnia.expect(i).to.have.all.keys('setor_id', 'setor_nome', 'atrasados', 'maior_atraso_dias');
    insomnia.expect(i.setor_id).to.be.a('number');
    insomnia.expect(i.setor_nome).to.be.a('string').and.not.empty;
    insomnia.expect(i.atrasados).to.be.above(0);
    insomnia.expect(i.maior_atraso_dias).to.be.above(0);
  });
});

insomnia.test("Setor com mais atrasos primeiro", () => {
  const q = corpo.data.map((i) => i.atrasados);
  insomnia.expect(q).to.eql([...q].sort((a, b) => b - a));
});

insomnia.test("Um item por setor (sem repetir)", () => {
  const ids = corpo.data.map((i) => i.setor_id);
  insomnia.expect(new Set(ids).size).to.eql(ids.length);
});

insomnia.test("Soma de atrasados = atrasadas de /dashboard/kpis", () => {
  const soma = corpo.data.reduce((t, i) => t + i.atrasados, 0);
  insomnia.expect(soma).to.eql(JSON.parse(insomnia.environment.get('kpis_manutencao')).atrasadas);
});

